/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assignments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `module_id` int(10) unsigned NOT NULL,
  `title` varchar(160) NOT NULL,
  `instructions` text NOT NULL,
  `max_score` tinyint(3) unsigned NOT NULL DEFAULT 100,
  PRIMARY KEY (`id`),
  UNIQUE KEY `module_id` (`module_id`),
  CONSTRAINT `fk_asg_mod` FOREIGN KEY (`module_id`) REFERENCES `modules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `assignments` WRITE;
/*!40000 ALTER TABLE `assignments` DISABLE KEYS */;
INSERT INTO `assignments` VALUES (1,3,'My personal AI plan','Choose one real task from your studies, work or community project (for example writing a report, planning a budget or preparing a presentation).\n\nIn 150 to 250 words describe: (1) how you would use an AI tool for part of the task, with one example prompt; (2) how you would check the result; and (3) what personal information you would never put into the tool.',100),(2,6,'Plan a project budget sheet','Imagine you are managing a small project with a budget, for example a school garden or a youth workshop.\n\nIn 120 to 200 words describe the spreadsheet you would build: the column headings you would use, three formulas you would include (and what each does), and one chart that would help your team understand the budget.',100),(3,9,'Analyse a viral message','Choose a message, post or forwarded story you have seen that you suspect may be false or misleading. Remove any personal names or numbers.\n\nIn 150 to 250 words: summarise the claim, show how you used at least two SIFT steps, say what you found, and explain how you would respond to the person who shared it.',100),(4,12,'A misunderstanding and what I learned','Think of a real misunderstanding you had with someone from a different background, language or way of working (you may change names).\n\nIn 150 to 250 words describe what happened, what each person may have expected, and how you would handle it now using ideas from this course.',100),(5,15,'Our team agreement','Imagine your team of four from Uganda, Kenya, Tanzania and Rwanda is about to start a project.\n\nWrite a team agreement of 150 to 250 words covering: your shared goal, how you will communicate (including what to do if someone has weak internet), how often you will meet and in which time zone, how decisions will be made, and how you will give feedback.',100),(6,18,'My STAR answer','Write a STAR answer of 150 to 250 words to this interview question: \"Tell me about a time you worked in a team to solve a problem.\"\n\nLabel the four parts: Situation, Task, Action, Result. Use a real example from school, work, volunteering or community life.',100),(7,21,'My climate-smart plot plan','Pick a real plot (home, school or community). In 150 to 250 words describe: (1) the soil and what you will do to improve it; (2) how you will save or manage water; and (3) which crops you will plant, when, and how you will spread risk.',100),(8,24,'My value-addition idea','Choose one crop and one product you could make from it. In 150 to 250 words explain: (1) how you would make it safely; (2) who the customers are; and (3) a rough cost and selling price per unit.',100),(9,27,'Farm business snapshot','Choose a crop or animal enterprise you know. In 150 to 250 words give: (1) the main costs and expected income for one season, with the gross margin; (2) two possible buyers and which you would choose; and (3) one way a group could improve your result.',100),(10,30,'My small livestock plan','Pick poultry, goats or rabbits. In 150 to 250 words explain: (1) housing and feeding for your starting number; (2) three health practices you will follow; and (3) your expected costs and income for the first three months.',100),(11,33,'My community health message','Pick one health habit (handwashing, safe water, food hygiene or first aid). In 150 to 250 words explain: (1) who your audience is; (2) how you would teach it in their language; and (3) how you would know it worked.',100),(12,36,'My wellbeing plan','In 150 to 250 words write: (1) three habits you will practise for wellbeing; (2) two people or places you can turn to for support; and (3) how you would help a friend who seems overwhelmed.',100),(13,39,'Energy plan for a household','Choose a household or small shop you know. In 150 to 250 words: (1) list the devices and estimate their daily watt-hours; (2) recommend a solar or clean-cooking solution; and (3) estimate monthly savings and how long it would take to pay back.',100),(14,42,'My one-page business plan','Write your one-page plan in 200 to 300 words: the problem, your product or service, your customers, price and costs, how you will reach customers, and your first three actions.',100),(15,45,'My 60-second story plan','Plan a 60-second story. In 150 to 250 words describe: (1) the person, the problem and the change; (2) your six key shots; and (3) how you will get permission and where you will share it.',100),(16,48,'A mini data project','Collect at least ten records about something real (for example weekly sales, rainfall or prices). In 150 to 250 words: (1) state your question; (2) give the total and average; and (3) describe one chart you would draw and what it shows.',100);
/*!40000 ALTER TABLE `assignments` ENABLE KEYS */;
