DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `courses` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(10) unsigned NOT NULL,
  `owner_id` int(10) unsigned NOT NULL,
  `title` varchar(160) NOT NULL,
  `slug` varchar(180) NOT NULL,
  `summary` varchar(300) NOT NULL,
  `description` text NOT NULL,
  `what_you_learn` text NOT NULL,
  `skills` varchar(300) DEFAULT NULL,
  `level` enum('Beginner','Intermediate','Advanced') NOT NULL DEFAULT 'Beginner',
  `hours_per_week` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `language` varchar(40) NOT NULL DEFAULT 'English',
  `color` varchar(7) NOT NULL DEFAULT '#0b5cd5',
  `has_certificate` tinyint(1) NOT NULL DEFAULT 1,
  `pass_mark` tinyint(3) unsigned NOT NULL DEFAULT 70,
  `status` enum('draft','published','archived') NOT NULL DEFAULT 'draft',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_status` (`status`),
  KEY `idx_cat` (`category_id`),
  KEY `fk_course_owner` (`owner_id`),
  FULLTEXT KEY `ft_courses` (`title`,`summary`,`skills`),
  CONSTRAINT `fk_course_cat` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `fk_course_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `courses` WRITE;
/*!40000 ALTER TABLE `courses` DISABLE KEYS */;
INSERT INTO `courses` VALUES (1,1,2,'AI Literacy for Everyday Life','ai-literacy-for-everyday-life','Understand what AI is, use AI tools with confidence, and know how to check, protect and question what they produce.','Artificial intelligence is already part of daily life, from mobile money fraud alerts to translation and search. This course explains AI in plain language, with no coding required.\n\nOver three weeks you will learn how AI systems learn from data, how to write clear requests for AI assistants, how to check their answers, and how to protect your privacy. You will finish with a personal plan for using AI responsibly in your studies or work.','Explain in simple words what AI is and how it learns from data\nWrite clear, specific requests (prompts) to get useful AI answers\nCheck AI output for mistakes and made-up facts\nProtect personal information when using AI tools\nDiscuss fairness, bias and how AI is changing jobs','AI literacy, Prompt writing, Fact checking, Digital safety, Ethical thinking','Beginner',3,'English','#0b5cd5',1,70,'published','2026-11-13 15:50:25','2026-11-13 15:50:25'),(2,1,2,'Digital Skills for the Workplace','digital-skills-for-the-workplace','Work safely and productively online: secure accounts, professional email, files, spreadsheets and cloud tools.','Employers expect new staff to work safely and confidently with digital tools. This beginner course covers the essentials: protecting your accounts, writing professional messages, organising files and making simple spreadsheets.\n\nEvery lesson works on a phone, and examples use situations common in East African workplaces and projects.','Create strong passwords and use two-step verification\nRecognise phishing and scam messages\nWrite clear, polite professional emails\nOrganise, name and back up files\nBuild a simple spreadsheet with formulas and a chart','Online safety, Email etiquette, File management, Spreadsheets, Cloud tools','Beginner',3,'English','#0e7c86',1,70,'published','2026-11-13 15:50:25','2026-11-13 15:50:25'),(3,2,3,'Critical Thinking and Spotting Misinformation','critical-thinking-and-spotting-misinformation','Question what you read, verify claims quickly, and build clear, evidence-based arguments.','False and misleading information spreads fast on messaging apps and social media, and it can harm health, money and trust in communities. Critical thinking is the habit of asking: how do I know this is true?\n\nThis course teaches practical, quick checks you can do on your phone, and the reasoning skills to explain your conclusions to others.','Recognise common thinking biases in yourself and others\nTell facts, opinions and claims apart\nUse the SIFT method to check a source in minutes\nSpot common reasoning mistakes\nBuild a short argument supported by evidence','Critical thinking, Fact checking, Media literacy, Argumentation, Decision making','Beginner',3,'English','#7a3fc4',1,70,'published','2026-11-13 15:50:26','2026-11-13 15:50:26'),(4,3,3,'Intercultural Communication across East Africa','intercultural-communication-across-east-africa','Communicate respectfully and clearly with people from different countries, languages and working styles.','East Africa brings together hundreds of languages and many ways of greeting, deciding and working. These differences are a strength, but they can also cause misunderstanding when people work together online.\n\nThis course helps you understand your own cultural habits, communicate clearly across languages, and run respectful virtual meetings across countries and time zones.','Describe how culture shapes communication and expectations\nAvoid stereotypes and assumptions\nUse plain language so everyone can understand\nPlan meetings across time zones and connection limits\nRepair a misunderstanding respectfully','Intercultural communication, Active listening, Plain language, Virtual meetings, Conflict resolution','Beginner',3,'English','#c2571a',1,70,'published','2026-11-13 15:50:26','2026-11-13 15:50:26'),(5,4,2,'Teamwork and Remote Collaboration','teamwork-and-remote-collaboration','Learn how effective teams plan, divide work, communicate and give feedback, even when members are in different countries.','Great ideas fail without good teamwork. This course prepares you for Level Two of YouthConnect, where you will work in multi-country teams on real projects.\n\nYou will learn how teams agree on roles and rules, how to plan with tasks and milestones, and how to collaborate on a slow connection. Completing this course unlocks team projects on the platform.','Agree team roles, goals and working rules\nBreak a project into tasks and milestones\nDefine what \"done\" means for each task\nCollaborate remotely with limited bandwidth\nGive and receive feedback constructively','Teamwork, Project planning, Remote collaboration, Feedback, Time management','Beginner',3,'English','#1f8a4c',1,70,'published','2026-11-13 15:50:26','2026-11-13 15:50:26'),(6,5,3,'Employability: CVs, Interviews and Online Presence','employability-cvs-interviews-and-online-presence','Identify your strengths, write a strong CV, perform well in interviews and build a professional online profile.','Many young people have real skills but struggle to show them to employers. This course turns your experience, including volunteering, study and community work, into a clear story.\n\nYou will write a focused CV, practise answering interview questions with the STAR method, and set up a professional online presence.','List your skills and transferable strengths\nWrite a clear one- to two-page CV tailored to a job\nAnswer interview questions using the STAR method\nPrepare questions to ask an employer\nBuild a professional online profile safely','CV writing, Interview skills, Personal branding, Networking, Goal setting','Beginner',3,'English','#b3261e',1,70,'published','2026-11-13 15:50:26','2026-11-13 15:50:26'),(7,6,3,'Climate-Smart Farming Basics','climate-smart-farming-basics','Grow more with less risk: healthy soil, smart water use and simple ways to adapt your farm to changing weather.','Rainfall is less predictable than it used to be, and many young farmers in East Africa feel it first. This course shows low-cost practices that protect harvests and soil.\n\nIn three weeks you will learn how to read your soil, save and manage water, and plan crops around weather risk. You finish with a one-page plan for a real plot, whether it is a family farm, a school garden or a community project.','Explain what makes soil healthy and how to improve it cheaply\nUse mulching, terraces and water harvesting to cope with dry spells and heavy rain\nChoose crops and planting dates to reduce weather risk\nUse rotation and intercropping to protect soil and income\nWrite a simple climate-smart plan for a plot','Soil health, Water management, Crop planning, Climate adaptation, Farm planning','Beginner',3,'English','#2e7d32',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(8,6,3,'Post-Harvest Handling and Value Addition','post-harvest-handling-and-value-addition','Stop losing food after harvest and earn more by drying, storing, processing and packaging your produce.','In many places a large share of what farmers grow is lost between the field and the market. Reducing those losses is like growing more without planting more.\n\nThis course covers harvesting at the right time, drying and storing grain safely, and turning raw produce into products people pay more for.','Explain where and why post-harvest losses happen\nHarvest, dry and store grain and legumes safely\nKeep fresh produce like tomatoes and mangoes in better condition\nPick a simple value-addition idea and check whether it can make money\nUse clean handling and basic packaging','Post-harvest handling, Storage, Food safety, Value addition, Packaging','Beginner',3,'English','#b7791f',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(9,6,3,'Agribusiness: Farm Records, Costs and Markets','agribusiness-farm-records-costs-and-markets','Run your farm like a business: keep records, know your costs, find buyers and group up to earn more.','Good farmers are not always profitable farmers. Profit comes from knowing your costs, choosing the right market and selling at the right time.\n\nThis course teaches simple record keeping, a gross margin calculation, how to find and compare buyers, and how groups and cooperatives can raise income.','Keep simple farm records of costs, yields and sales\nCalculate gross margin per crop or animal\nCompare markets and buyers and negotiate a fair price\nUnderstand how groups and cooperatives help small farmers\nUse mobile money safely for farm payments','Record keeping, Costing, Marketing, Negotiation, Cooperatives','Intermediate',3,'English','#00796b',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(10,6,3,'Poultry and Small Livestock Basics','poultry-and-small-livestock-basics','Start small with chickens, goats or rabbits: housing, feeding, disease prevention and the numbers that keep it profitable.','Small livestock are one of the quickest ways for a young person to start earning in agriculture: they need little land and grow fast. But poor housing, feeding and hygiene can wipe out a flock in days.\n\nThis course covers the basics of housing, feeding and health for poultry and small livestock, and how to work out whether your enterprise pays.','Plan safe, clean housing for chickens and small animals\nFeed animals correctly and give clean water\nPrevent common diseases with hygiene, vaccination and early action\nKeep simple production and cost records\nKnow when to call a veterinary or extension officer','Animal husbandry, Animal health, Feeding, Biosecurity, Enterprise records','Beginner',3,'English','#c05621',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(11,7,2,'First Aid and Community Health Basics','first-aid-and-community-health-basics','Know what to do in the first minutes of an emergency and how to help your community stay healthy.','In an emergency the first few minutes matter, often before any health worker arrives. This course gives you simple, widely recommended first aid skills and practical habits that prevent illness in homes and communities.\n\nIt is an introduction, not a replacement for a certified first aid course or medical care. Always call emergency services or go to a health facility for serious conditions.','Check a scene for safety and call for help properly\nTreat bleeding, burns, cuts and choking with basic first aid\nRecognise when someone needs urgent medical help\nPractise handwashing, safe water and food hygiene\nShare health messages respectfully in your community','First aid, Emergency response, Hygiene, Health communication, Prevention','Beginner',3,'English','#c62828',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(12,7,2,'Mental Health and Wellbeing for Young People','mental-health-and-wellbeing-for-young-people','Understand stress, build healthy habits and support friends, without stigma.','Young people carry real pressure: exams, jobs, money, family expectations and social media. Looking after your mind is as important as looking after your body.\n\nThis course gives practical tools for coping with stress, building routines and supporting others. It is for learning and is not a substitute for professional care. If you or someone is in danger, contact local emergency services or a trusted adult straight away.','Recognise common signs of stress, anxiety and low mood\nUse simple habits for sleep, movement, connection and calm\nListen to a friend in difficulty without judging\nKnow when and where to find professional help\nUse social media in healthier ways','Stress management, Wellbeing, Active listening, Help-seeking, Digital wellbeing','Beginner',3,'English','#6a4c93',1,70,'published','2026-11-13 15:50:27','2026-11-13 15:50:27'),(13,8,2,'Solar Energy and Clean Cooking Basics','solar-energy-and-clean-cooking-basics','Understand how solar power and clean cooking work, what they cost and how young people can build businesses around them.','Millions of homes and small businesses in East Africa still depend on kerosene, charcoal or unreliable grid power. Solar lights, solar home systems and clean cookstoves are changing that.\n\nThis course explains in plain language how solar systems work, how to size one for a household, and how clean cooking saves money and protects health. It is an introduction: always use a qualified technician for wiring.','Explain how a solar panel, battery and controller work together\nWork out how much power a household needs\nCompare solar options and costs, including pay-as-you-go\nExplain the health and cost benefits of clean cookstoves\nIdentify energy business opportunities for young people','Solar basics, Energy planning, Clean cooking, Safety, Green enterprise','Beginner',3,'English','#f59e0b',1,70,'published','2026-11-13 15:50:28','2026-11-13 15:50:28'),(14,9,3,'Starting a Small Business: From Idea to First Customers','starting-a-small-business-from-idea-to-first-customers','Test your idea, price it, find your first customers and keep your money in order.','Many young people have good ideas but not a plan to test them cheaply. This course walks you through the steps of starting small: finding a real problem, talking to customers, pricing and tracking your money.\n\nYou finish with a one-page business plan you can show a mentor, a group or a lender.','Turn a problem into a business idea and test it with customers\nPrice a product or service so you make a profit\nPlan costs, cash and simple records\nSell, promote and keep customers\nWrite a one-page business plan','Idea testing, Pricing, Cash planning, Marketing, Business planning','Beginner',3,'English','#0f766e',1,70,'published','2026-11-13 15:50:28','2026-11-13 15:50:28'),(15,10,2,'Digital Storytelling with a Phone','digital-storytelling-with-a-phone','Tell stories that matter with photos, short videos and sound, using only a smartphone and free tools.','A phone is a camera, a recorder and an editing suite. Young people use them to share farm tips, promote small businesses, raise awareness and tell community stories.\n\nThis course teaches how to plan a short story, capture good photos, video and sound, and share responsibly and respectfully.','Plan a short story with a beginning, middle and end\nTake clear photos and steady video with good light and sound\nEdit with free mobile apps\nGet consent and respect people\'s dignity\nShare and measure your story\'s reach','Storytelling, Photography, Video, Editing, Media ethics','Beginner',3,'English','#be185d',1,70,'published','2026-11-13 15:50:28','2026-11-13 15:50:28'),(16,11,2,'Data Basics: Collect, Clean and Read Data','data-basics-collect-clean-and-read-data','Collect simple data, tidy it in a spreadsheet and read charts, so you can make better decisions in farming, business or projects.','Data helps farmers decide when to plant, shopkeepers decide what to stock and project teams show results. You do not need to code to start.\n\nThis course covers asking a clear question, collecting data carefully, cleaning and summarising it in a spreadsheet, and reading charts honestly.','Turn a question into data you can collect\nRecord data neatly and consistently\nClean data and calculate totals and averages\nChoose and read a simple chart\nSpot misleading charts and protect people\'s privacy','Data collection, Spreadsheets, Averages, Charts, Data ethics','Beginner',3,'English','#1d4ed8',1,70,'published','2026-11-13 15:50:28','2026-11-13 15:50:28');
