INSERT INTO `discussion_posts` VALUES (1,1,6,NULL,'My bank sends a warning when a payment looks unusual. I guess that is AI spotting a pattern. What did you find?',0,0,'2026-11-13 15:50:29'),(2,1,7,NULL,'My phone keyboard suggests Swahili and English words depending on what I type. Great example of AI learning my habits.',0,0,'2026-11-13 15:50:29'),(3,1,2,2,'Exactly, Wanjiru. The keyboard learns from patterns in your typing. Remember that this is also why privacy settings matter.',0,0,'2026-11-13 15:50:29');
