/*!40000 ALTER TABLE `modules` DISABLE KEYS */;
INSERT INTO `modules` VALUES (1,1,1,'What is AI, really?','See where AI already shows up in your life and how machines learn patterns from examples.',3),(2,1,2,'Using AI tools well','Write clear prompts and learn why every AI answer needs to be checked.',3),(3,1,3,'AI, ethics and your future','Protect your privacy, understand bias, and plan how to use AI responsibly.',3),(4,2,1,'Working online safely','Protect your accounts and spot scams before they cost you.',3),(5,2,2,'Everyday productivity tools','Communicate professionally by email and work with documents in the cloud.',3),(6,2,3,'Working with files and data','Organise your files and build a simple spreadsheet with formulas and a chart.',3),(7,3,1,'How we think','Understand the mental shortcuts that make all of us easy to fool.',3),(8,3,2,'Checking claims quickly','Use the SIFT method and simple tools to verify what you see online.',3),(9,3,3,'Reasoning and arguing well','Avoid common reasoning mistakes and build an argument that others can trust.',3),(10,4,1,'Culture and communication','Understand how culture shapes what we say, how we say it and what we expect.',3),(11,4,2,'Communicating across languages','Use plain language and listening skills so that everyone understands.',3),(12,4,3,'Working across borders online','Plan inclusive meetings across countries, time zones and connection limits, and repair misunderstandings.',3),(13,5,1,'How good teams work','Set a shared goal, clear roles and simple team rules.',3),(14,5,2,'Planning and tracking work','Break a project into tasks and milestones and agree what \"done\" means.',3),(15,5,3,'Collaborating remotely','Communicate well, give useful feedback and handle conflict when you cannot meet in person.',3),(16,6,1,'Know your strengths','Turn your experience into skills employers value.',3),(17,6,2,'CVs and applications','Write a focused CV and a short cover letter tailored to the job.',3),(18,6,3,'Interviews and online presence','Answer questions with the STAR method and build a professional profile safely.',3),(19,7,1,'Healthy soil, healthy harvest','Understand what soil is made of and the cheap ways to make it better.',3),(20,7,2,'Water: too little, too much','Save rain, use it wisely and protect fields from erosion.',3),(21,7,3,'Planning around risk','Choose crops, dates and rotations that protect your income.',3),(22,8,1,'Harvest right, dry right','Timing, drying and the first steps that decide quality.',3),(23,8,2,'Safe storage and fresh produce','Keep grain safe for months and fresh produce fresh for days.',3),(24,8,3,'Adding value','Turn raw produce into products and test whether they can earn money.',3),(25,9,1,'Know your numbers','Records, costs and what you actually earn.',3),(26,9,2,'Finding and keeping buyers','Where to sell, how to compare buyers and what a fair deal looks like.',3),(27,9,3,'Stronger together','Groups, cooperatives, savings and safe mobile money.',3),(28,10,1,'Housing and feeding','A good start: the right house, the right feed, clean water.',3),(29,10,2,'Keeping animals healthy','Biosecurity, vaccination and spotting problems early.',3),(30,10,3,'Does it pay?','Records, costs, selling and growing step by step.',3),(31,11,1,'Emergencies: the first minutes','Stay safe, call for help and handle the most common emergencies.',3),(32,11,2,'Choking, fainting, fever and seizures','Know the signs, act calmly and know when it is urgent.',3),(33,11,3,'Healthy homes and communities','Hygiene, safe water and talking about health.',3),(34,12,1,'Understanding stress','What stress is, what it does and what helps.',3),(35,12,2,'Habits that protect you','Sleep, connection and managing the online world.',3),(36,12,3,'Helping others and getting help','Listen well, avoid stigma and know where to find support.',3),(37,13,1,'How solar works','From sunshine to light: panel, battery, controller and load.',3),(38,13,2,'Choosing and affording solar','Compare products, avoid poor quality and understand pay-as-you-go.',3),(39,13,3,'Clean cooking and opportunities','Cookstoves, health and green businesses.',3),(40,14,1,'Idea and customers','Start with a problem people already pay to solve.',3),(41,14,2,'Pricing and money','Cover your costs, make a profit and protect your cash.',3),(42,14,3,'Customers and a plan','Win customers, keep them and write a one-page plan.',3),(43,15,1,'Find the story','What to say, who it is for and how to plan it.',3),(44,15,2,'Capture with your phone','Light, framing and clean sound.',3),(45,15,3,'Edit, share and do it ethically','Free editing apps, consent and reach.',3),(46,16,1,'Ask and collect','Start with a question and collect data you can trust.',3),(47,16,2,'Clean and summarise','Tidy a table, then total and average it in a spreadsheet.',3),(48,16,3,'Charts and honest data','Choose the right chart and spot misleading ones.',3);
