INSERT INTO `projects` VALUES (1,'587de707c1f5055f',1,'Smallholder Planting Advisor','Agriculture & food security','A low-data mobile web tool that tells smallholder farmers the best time to plant, using local weather and soil information.','Smallholder farmers in Uganda, Kenya, Tanzania and Rwanda often plant too early or too late because rainfall has become less predictable, and advice from extension officers is hard to reach.','We will combine farmer interviews (agriculture), a lightweight web app that works on basic smartphones (software), seasonal rainfall data analysis (data) and local environmental conditions (environment) into a simple planting calendar delivered in English and Swahili.','We aim to reach 200 farmers in a pilot, reduce failed plantings, and measure the change in yield reported at the end of the season.','changes_requested',4,'2026-11-13 15:50:29','2026-11-13 15:50:29'),(2,'539812edc7096e07',2,'Borehole Water Quality Map','Water & sanitation','A shared map showing which community boreholes have been tested and whether the water is safe to drink.',NULL,NULL,NULL,'draft',1,'2026-11-13 15:50:29','2026-11-13 15:50:29');
/*!40000 ALTER TABLE `projects` ENABLE KEYS */;
UNLOCK TABLES;
