LOCK TABLES `questions` WRITE;
/*!40000 ALTER TABLE `questions` DISABLE KEYS */;
INSERT INTO `questions` VALUES (1,1,1,'Which statement best describes artificial intelligence?','AI systems learn patterns from data. They do not think like people.'),(2,1,2,'What is \"training data\"?','Training data is the set of examples used to teach the system.'),(3,1,3,'An AI crop-disease app was trained only on photos from one region. What risk does this create?','One-sided training data can make results unreliable for people or places not represented.'),(4,1,4,'Which of these is the best example of everyday AI?','Speech-to-text learns patterns in how language sounds.'),(5,2,1,'Which prompt is most likely to give a useful answer?','Specific context, task and format make answers more useful.'),(6,2,2,'What is a \"hallucination\" in AI?','AI can invent facts that sound believable.'),(7,2,3,'An AI tool gives you a statistic for your report. What should you do?','Always verify numbers and facts yourself.'),(8,2,4,'If the first AI answer is too long, what is a good next step?','You can improve results by refining your request step by step.'),(9,3,1,'Which of these should you NEVER type into an AI chatbot?','PINs and passwords must stay private.'),(10,3,2,'Why can AI systems be biased?','Biased data leads to biased results.'),(11,3,3,'Which approach best prepares you for a workplace with more AI?','Judgement, communication and learning remain valuable.'),(12,3,4,'Before sharing a classmate\'s photo with an AI app, you should:','Other people\'s personal information needs their consent.'),(13,4,1,'Which password is strongest?','Long, unique passphrases are strong and easier to remember.'),(14,4,2,'What does two-step verification add?','A second step protects the account even if the password leaks.'),(15,4,3,'A message says \"Send your mobile money PIN to claim your prize.\" This is:','Nobody legitimate asks for your PIN.'),(16,4,4,'What is the safest response to a suspicious link?','Verify through a separate trusted channel.'),(17,5,1,'What makes a good email subject line?','A clear subject helps the reader act quickly.'),(18,5,2,'What is a benefit of editing documents in the cloud?','Cloud tools support collaboration and version history.'),(19,5,3,'Which closing is most appropriate for a work email?','A polite close with your name is professional.'),(20,5,4,'When a document contains private information you should share it with:','Limit access to people who need it.'),(21,6,1,'Which formula adds the numbers in cells B2 to B10?','SUM adds a range of cells.'),(22,6,2,'A chart is best used to:','Charts summarise patterns visually.'),(23,6,3,'Why keep important files in two places?','Backups protect your work.'),(24,6,4,'Which file name is clearest?','Descriptive names with dates and versions are easy to find.'),(25,7,1,'Which of these is an opinion?','Taste is a personal view, not a checkable fact.'),(26,7,2,'What is confirmation bias?','We tend to favour evidence that supports our existing beliefs.'),(27,7,3,'A message makes you very angry and says \"Share now!\" What should you do first?','Strong emotion is a signal to slow down and verify.'),(28,7,4,'A claim needs:','Evidence, not popularity, supports a claim.'),(29,8,1,'What does the \"S\" in SIFT remind you to do?','The first step is to stop.'),(30,8,2,'You see a dramatic photo said to be from yesterday. What is a good check?','Reverse image search often reveals old or reused images.'),(31,8,3,'\"Find better coverage\" means:','Reliable corroboration is stronger than repetition.'),(32,8,4,'A short clip of a speech seems to say something shocking. What should you consider?','Missing context can change the meaning.'),(33,9,1,'\"Everyone from that village is dishonest because one person cheated me.\" This is:','One case does not describe everyone.'),(34,9,2,'Ice cream sales and sunburn both rise in summer. Which conclusion is sound?','Correlation does not prove causation.'),(35,9,3,'A good argument includes:','Reasons must be supported by evidence.'),(36,9,4,'Responding to the strongest opposing point makes your argument:','Fairly answering objections builds credibility.'),(37,10,1,'Which part of culture is hardest to see?','The hidden part of culture includes values and beliefs.'),(38,10,2,'A teammate stays silent when you propose a plan. The best response is to:','Silence can mean many things.'),(39,10,3,'Which statement about communication styles is best?','Respect different styles and check understanding.'),(40,10,4,'A stereotype is:','Stereotypes ignore individual differences.'),(41,11,1,'Which sentence is plainer?','Short, direct sentences are easier to understand.'),(42,11,2,'Why summarise decisions in writing after a call?','Written summaries reduce misunderstandings.'),(43,11,3,'Repeating back what you heard is called:','It helps catch errors early.'),(44,11,4,'Which is best when writing to teammates who use English as a second language?','Clear, simple writing includes everyone.'),(45,12,1,'When it is 3 pm in Kampala, what time is it in Kigali?','Rwanda uses Central Africa Time, UTC+2, one hour behind East Africa Time.'),(46,12,2,'What helps teammates with weak connections?','Low-bandwidth options make participation fair.'),(47,12,3,'What is a good first step when you disagree after a misunderstanding?','Calm, specific conversation repairs trust.'),(48,12,4,'Why write the time zone with the meeting time?','Time zones differ within the region.'),(49,13,1,'A shared team goal should be:','A clear goal aligns everyone.'),(50,13,2,'Why include different disciplines in one team?','Complementary skills make teams stronger.'),(51,13,3,'A team agreement is best written:','Early, shared rules prevent conflict.'),(52,13,4,'Which is NOT usually part of a team agreement?','Passwords are private and never belong in a shared document.'),(53,14,1,'What is a milestone?','Milestones mark important progress points.'),(54,14,2,'Each task should have:','Clear ownership drives action.'),(55,14,3,'A \"definition of done\" helps because it:','It avoids confusion about what finished means.'),(56,14,4,'A simple three-column board shows:','It makes progress visible.'),(57,15,1,'When your connection is weak, which option is best for a team discussion?','Use the lightest tool that works for everyone.'),(58,15,2,'Good feedback is:','Focus on the work and suggest improvements.'),(59,15,3,'Why record decisions in writing?','Written records keep everyone aligned.'),(60,15,4,'If a conflict continues in your team, you should:','Seeking support early is a sign of maturity.'),(61,16,1,'Which is a transferable skill?','Communication applies to nearly every job.'),(62,16,2,'Organising a community event can show:','Volunteer experience builds real skills.'),(63,16,3,'A good career goal is:','Clear goals guide action.'),(64,16,4,'Before applying for jobs, you should first:','Self-knowledge helps you target well.'),(65,17,1,'Which line is strongest on a CV?','Specific actions with numbers show impact.'),(66,17,2,'How long should a CV for an early-career applicant normally be?','Short and focused is best.'),(67,17,3,'Tailoring your CV means:','Tailoring shows you read the advert and fit it.'),(68,17,4,'A good cover letter is:','Keep it clear and relevant.'),(69,18,1,'What does STAR stand for?','STAR structures a clear example.'),(70,18,2,'In the \"Action\" step you should describe:','Interviewers want to know your own contribution.'),(71,18,3,'A genuine employer will:','Requests for payment are a classic scam.'),(72,18,4,'Before applying, your public social media should be:','Employers often look at your online presence.'),(73,19,1,'Which of these adds organic matter to soil?','Compost and manure feed soil organisms and improve structure.'),(74,19,2,'What is the main benefit of mulch?','Mulch protects the surface and keeps moisture in.'),(75,19,3,'Why are beans and groundnuts useful in rotation?','Legumes fix nitrogen, which helps the next crop.'),(76,19,4,'Soil that stays sticky and drains slowly is most likely:','Clay soils hold water and drain slowly.'),(77,20,1,'What do contour bunds do?','Bunds follow the slope line and trap water and soil.'),(78,20,2,'When is the best time to water crops to reduce evaporation?','Cooler hours lose less water to evaporation.'),(79,20,3,'Which is the cheapest way to cut water loss?','Mulch costs little and keeps moisture in.'),(80,21,1,'Why stagger planting dates?','Spreading dates spreads weather risk.'),(81,21,2,'Which sequence is a sensible rotation?','Alternating cereals and legumes protects soil and breaks pest cycles.'),(82,21,3,'What is intercropping?','Intercrops share space and reduce risk.'),(83,22,1,'Why must grain be dried properly?','Moulds thrive in moisture and some produce aflatoxin.'),(84,22,2,'Where should grain be dried?','Drying off the ground keeps grain cleaner and drier.'),(85,22,3,'Post-harvest losses are best described as:','They occur after the crop leaves the plant.'),(86,23,1,'Why do airtight bags protect grain?','Hermetic storage starves insects of oxygen.'),(87,23,2,'Which habit reduces damage to fresh tomatoes?','Bruising and heat speed up rot.'),(88,23,3,'Why stack sacks on pallets?','Air circulation and distance from damp reduce spoilage.'),(89,24,1,'What does value addition mean?','Processing, grading and packaging raise the price a product can earn.'),(90,24,2,'What should you ask before starting a product?','Demand and cost decide whether it can make money.'),(91,24,3,'What helps a food product earn customer trust?','Hygiene and clear information build trust.'),(92,25,1,'Gross margin equals:','It shows what is left after direct costs.'),(93,25,2,'Why keep farm records?','Records guide better decisions.'),(94,25,3,'A farmer earns 1,000,000 from sales and spends 700,000 on direct costs. The gross margin is:','1,000,000 minus 700,000 equals 300,000.'),(95,26,1,'Which factor should you compare when choosing a buyer?','The best buyer is the one with the best total deal.'),(96,26,2,'Why know your costs before negotiating?','Costs set the floor for your price.'),(97,26,3,'Why agree payment terms clearly?','Clear terms protect both sides.'),(98,27,1,'What is one advantage of selling as a group?','Volume and organisation create bargaining power.'),(99,27,2,'What keeps a savings group healthy?','Transparency builds trust.'),(100,27,3,'Which mobile money habit is safe?','Keep your PIN private and confirm recipients.'),(101,28,1,'Which is the most important feed for animals?','Animals can survive longer without feed than without water.'),(102,28,2,'A good animal house should be:','Dry, clean, airy housing reduces disease.'),(103,28,3,'Why store feed in a dry place?','Mould and toxins are harmful.'),(104,29,1,'What is biosecurity?','Biosecurity stops diseases from entering and spreading.'),(105,29,2,'What should you do with a new animal bought from another farm?','Quarantine reveals disease before it spreads.'),(106,29,3,'Which sign needs quick action?','Sudden group illness can mean a serious disease.'),(107,30,1,'Why keep daily records?','Records show trends and costs.'),(108,30,2,'The safest way to grow an animal enterprise is to:','Learning at small scale limits risk.'),(109,30,3,'Which is usually the biggest cost for chickens?','Feed is commonly the largest share of cost.'),(110,31,1,'What is the first thing to do at an emergency scene?','Your safety comes first so you can help.'),(111,31,2,'How do you treat a burn?','Running water cools the burn and reduces damage.'),(112,31,3,'How do you control heavy bleeding?','Firm continuous pressure helps stop bleeding.'),(113,32,1,'What should you NOT do during a seizure?','Objects in the mouth can cause injury and block breathing.'),(114,32,2,'A person cannot cough, speak or breathe because of choking. You should:','Back blows and thrusts can clear the airway.'),(115,32,3,'A baby has a fever. The safest action is to:','Fever in babies needs professional assessment.'),(116,33,1,'When should you wash your hands with soap?','These are key moments for stopping germs spreading.'),(117,33,2,'Which is a trustworthy source of health information?','Use official or professional sources.'),(118,33,3,'Why should you keep raw and cooked food apart?','Cross-contamination causes food poisoning.'),(119,34,1,'Which is true about mental health?','Mental health is part of everyone\'s life.'),(120,34,2,'Which is a healthy way to cope with stress?','Simple habits and support reduce stress.'),(121,34,3,'When might feelings become a concern?','Severity and duration matter.'),(122,35,1,'Which habit helps sleep?','Routine supports good sleep.'),(123,35,2,'Why can social media comparison hurt?','Comparisons are often unfair.'),(124,35,3,'Which is a protective factor for wellbeing?','Connection protects mental health.'),(125,36,1,'When a friend opens up, a good first response is:','Listening and respect are the start of support.'),(126,36,2,'What should you do if someone talks about harming themselves?','Safety comes before secrecy.'),(127,36,3,'Asking for help is:','Seeking support is a sensible step.'),(128,37,1,'What does a charge controller do?','It regulates charging to protect the battery.'),(129,37,2,'A 10 W bulb is on for 3 hours. How much energy does it use?','Energy equals power times time: 10 x 3 = 30 Wh.'),(130,37,3,'Why does a solar system need a battery?','The battery stores energy for when the sun is not shining.'),(131,38,1,'What should you check before buying a solar product?','Quality and support protect your investment.'),(132,38,2,'What is pay-as-you-go solar?','PAYG spreads the cost over time.'),(133,38,3,'How do you estimate payback time?','Price divided by monthly saving gives months to payback.'),(134,39,1,'What is a health benefit of improved cookstoves?','Less smoke means fewer lung problems.'),(135,39,2,'Which is a clean cooking option?','LPG and biogas burn cleaner than open fires.'),(136,39,3,'Before starting an energy business you should:','Skills and planning reduce risk.'),(137,40,1,'A good business idea usually starts with:','Real problems create real demand.'),(138,40,2,'What is a good first test?','Small tests are cheap and informative.'),(139,40,3,'If customers do not want to pay, you should:','Feedback helps you improve.'),(140,41,1,'Price should at least cover:','Without covering costs plus profit, the business loses money.'),(141,41,2,'Why separate business and personal money?','Mixing money hides true results.'),(142,41,3,'Profit equals:','What remains after costs.'),(143,42,1,'Which action helps you keep customers?','Reliability and listening build loyalty.'),(144,42,2,'What belongs in a one-page plan?','A short plan covers the key decisions.'),(145,42,3,'Why share your plan with a mentor?','Outside feedback strengthens plans.'),(146,43,1,'A story usually has:','People and change make a story.'),(147,43,2,'What is a storyboard?','It plans your sequence before you film.'),(148,43,3,'Why decide your audience first?','Audience guides content and style.'),(149,44,1,'For better photos you should:','Light on the subject improves clarity.'),(150,44,2,'How do you get clearer sound?','Distance and noise reduce quality.'),(151,44,3,'Why record each video shot for several seconds?','Extra length helps cuts and transitions.'),(152,45,1,'Why add captions?','Many people watch muted or cannot hear.'),(153,45,2,'Before filming someone you should:','Consent is essential.'),(154,45,3,'How can you learn what worked after sharing?','Feedback shows what to repeat.'),(155,46,1,'A good data question is:','Clear questions guide what to collect.'),(156,46,2,'Why use the same units?','Consistent units avoid mistakes.'),(157,46,3,'Before collecting data about people you should:','Respect privacy and consent.'),(158,47,1,'In a tidy table each row is:','One row per record keeps analysis simple.'),(159,47,2,'Which formula adds the numbers in B2 to B10?','SUM adds a range of cells.'),(160,47,3,'Why can an average mislead?','Unusual values can distort the average.'),(161,48,1,'Which chart suits change over time?','Lines show trends.'),(162,48,2,'Why can a truncated axis mislead?','Axes that skip zero exaggerate differences.'),(163,48,3,'When sharing data about people you should:','Anonymising protects privacy.');
